const input = $input.first().json;
const e164 = /^\+?[1-9]\d{6,14}$/;
if (typeof input.phoneNumber !== 'string' || !e164.test(input.phoneNumber)) {
  throw new Error('U2 entry-guard: phoneNumber missing or not E.164: ' + JSON.stringify(input.phoneNumber));
}
if (typeof input.messageType !== 'string' || input.messageType.length === 0) {
  throw new Error('U2 entry-guard: messageType missing or empty');
}
if (typeof input.reason !== 'string' || input.reason.length === 0) {
  throw new Error('U2 entry-guard: reason missing or empty');
}
const thr = Number(input.blockThreshold);
if (!Number.isInteger(thr) || thr < 1) {
  throw new Error('U2 entry-guard: blockThreshold missing or not a positive integer: ' + JSON.stringify(input.blockThreshold));
}
// blockReason: the exact value to store in users.blocked_reason if/when this call trips the block.
// Composed by the CALLER (e.g. 'threshold_non_text', 'threshold_garbage', 'abuse') — U2 stores it verbatim.
if (typeof input.blockReason !== 'string' || input.blockReason.length === 0) {
  throw new Error('U2 entry-guard: blockReason missing or empty');
}
return [{ json: {
  phoneNumber: input.phoneNumber,
  messageType: input.messageType,
  reason: input.reason,
  messageContent: (input.messageContent === undefined || input.messageContent === null) ? null : String(input.messageContent),
  blockThreshold: thr,
  blockReason: input.blockReason
} }];

