// U2 — assemble the admin auto-block alert. Routed to the admin-commands channel.
// Accurate for both abuse (instant, count=1) and threshold (count=N) blocks.
const env = $('Entry Guard').item.json;
const cnt = $('Count 30-Day Drops').item.json.drop_count;
const reasonStored = $('Auto-Block Upsert').item.json.blocked_reason;
const raw = (env.messageContent === null || env.messageContent === undefined || env.messageContent === '') ? '(no text)' : String(env.messageContent);
const msgClip = raw.length > 500 ? raw.slice(0, 500) + '\u2026' : raw;
const channelId = 'C0A5B0ZE81E';
const messageText =
  '\ud83d\udeab A number was automatically blocked.\n\n' +
  '*Number:* ' + env.phoneNumber + '\n' +
  '*Reason:* ' + reasonStored + '\n' +
  '*Flagged/dropped messages (last 30 days):* ' + cnt + '\n' +
  '*Most recent:* ' + env.messageType + ' / ' + env.reason + '\n' +
  '*Their last message:* "' + msgClip + '"\n\n' +
  'No reply was sent. The number is now blocked.';
return [{ json: { channelId, messageText } }];

